// Digi's Inventory and QoL: Backpack At Stations, Store Nearby, Store In Backpacks, Safe Item Move, Achievement Keeper, Keep Rested, Effect Details, Skill XP.
// One plugin and one settings file for all of them: F1 shows a switch per sub-mod at the top, then each sub-mod's
// settings under its name. Generated by make_combined.py; the sub-mods' code is in Modules/.
using BepInEx;
using DigiCore;

namespace DigiQoL
{
    [BepInPlugin(Guid, Name, Version)]
    [BepInDependency("LuminairPrime.valheim.localcraftfromstorageprime", BepInDependency.DependencyFlags.SoftDependency)]
    [BepInDependency("Searica.Valheim.TerrainTools", BepInDependency.DependencyFlags.SoftDependency)]
    [BepInDependency("ValheimLegends", BepInDependency.DependencyFlags.SoftDependency)]
    [BepInDependency("cdev.equipmentslots", BepInDependency.DependencyFlags.SoftDependency)]
    [BepInDependency("com.alan.bettersmelter", BepInDependency.DependencyFlags.SoftDependency)]
    [BepInDependency("ishid4.mods.betterarchery", BepInDependency.DependencyFlags.SoftDependency)]
    [BepInDependency("randyknapp.mods.epicloot", BepInDependency.DependencyFlags.SoftDependency)]
    [BepInDependency("vapok.mods.adventurebackpacks", BepInDependency.DependencyFlags.SoftDependency)]
    public class Plugin : DigiPlugin
    {
        public const string Guid = "digi.valheim.qol";
        public const string Name = "Digi's Inventory and QoL";
        public const string Version = "1.0.37";

        protected override ModuleInfo[] Modules { get; } =
        {
            new ModuleInfo(typeof(global::BackpackAtStations.Plugin), "Backpack At Stations", "digi.valheim.backpackatstations", "Open your Adventure Backpack at crafting stations (older Adventure Backpacks; 2.4 and newer do it themselves).", new[] { "vapok.mods.adventurebackpacks" }, true),
            new ModuleInfo(typeof(global::BackpackQuickOpen.Plugin), "Backpack Quick Open", "digi.valheim.backpackquickopen", "Middle-click a backpack in your inventory to open it without wearing it, e.g. while you wear a cape.", new[] { "vapok.mods.adventurebackpacks" }, true),
            new ModuleInfo(typeof(global::StoreNearby.Plugin), "Store Nearby", "digi.valheim.storenearby", "A Store Nearby button under your inventory (and an open backpack): your items go into the chests around you that already hold them; a checkbox per chest; replaces Local Craft From Storage's.", null, true),
            new ModuleInfo(typeof(global::StoreInBackpacks.Plugin), "Store In Backpacks", "digi.valheim.storeinbackpacks", "A To Backpacks button next to Store Nearby: your items go into the backpacks you carry that already hold them.", new[] { "vapok.mods.adventurebackpacks" }, true),
            new ModuleInfo(typeof(global::SafeItemMove.Plugin), "Safe Item Move", "digi.valheim.safeitemmove", "Items you drag around your inventory can no longer vanish, chests never flash another chest's items, holding E on a chest no longer dumps your stacks into it, and Place stacks leaves your hotbar alone.", null, true),
            new ModuleInfo(typeof(global::AchievementKeeper.Plugin), "Achievement Keeper", "digi.valheim.achievementkeeper", "Steam achievements keep working with mods.", null, true),
            new ModuleInfo(typeof(global::KeepRested.Plugin), "Keep Rested", "digi.valheim.keeprested", "Your Rested buff stays when you log out and back in, and resting gives Rested twice as fast.", null, true),
            new ModuleInfo(typeof(global::EffectDetails.Plugin), "Effect Details", "digi.valheim.effectdetails", "Effect tooltips show the values the game leaves out, e.g. All damage: +10% for Aesir mead, and weapon tooltips a damage total.", null, true),
            new ModuleInfo(typeof(global::CameraClipFix.Plugin), "Camera Clip Fix", "digi.valheim.cameraclipfix", "In third person the camera no longer goes partly into a floor above you, a roof or a wall: it comes closer instead.", null, true),
            new ModuleInfo(typeof(global::ChestFillOrder.Plugin), "Chest Fill Order", "digi.valheim.chestfillorder", "What you put into a chest, cart, ship or backpack goes into the first free slot from the top left, instead of the game's bottom row first.", null, true),
            new ModuleInfo(typeof(global::ChestSorter.Plugin), "Chest Sorter", "digi.valheim.chestsorter", "Chests sort themselves when you open them and after Store Nearby: grouped by kind, A-Z, from the top left, stacks merged.", null, true),
            new ModuleInfo(typeof(global::ItemPickupFix.Plugin), "Item Pickup Fix", "digi.valheim.itempickupfix", "Items from other mods that cannot be picked up and fall through the floor (a collider without a shape) get a working one, and Equipment Slots' quick slot key V no longer switches the game's auto pickup off too.", null, true),
            new ModuleInfo(typeof(global::SellToHaldor.Plugin), "Sell To Haldor", "digi.valheim.selltohaldor", "Haldor also buys your food and feasts (a box in his window) and every kind of hide and leather.", null, true),
            new ModuleInfo(typeof(global::LighterInventory.Plugin), "Lighter Inventory", "digi.valheim.lighterinventory", "An open inventory costs less: items and the recipe panel are redrawn when something changes instead of every frame, also Equipment Slots' panel.", null, true),
            new ModuleInfo(typeof(global::SkillXp.Plugin), "Skill XP", "digi.valheim.skillxp", "The Skills window shows each skill's XP, e.g. 24  12/63.", null, true),
            new ModuleInfo(typeof(global::AutoCloseDoors.Plugin), "Auto Close Doors", "digi.valheim.autoclosedoors", "Doors you built close by themselves 15 seconds after opening, never on someone standing in the doorway.", null, true),
            new ModuleInfo(typeof(global::CompactStatusEffects.Plugin), "Compact Status Effects", "digi.valheim.compactstatuseffects", "The effect icons top right take less room: smaller icons, no names under them, and the effects that never change (what you wear, always-on forsaken powers) left out.", null, true),
            new ModuleInfo(typeof(global::HudGrid.Plugin), "HUD Grid", "digi.valheim.hudgrid", "Better Archery's arrow slots, Valheim Legends' abilities and CDEV's quick slots in one tidy grid beside the health bar, in the hotbar's look.", null, true),
        };
    }
}
